#!/usr/bin/env python3
"""Rebuild both signed Royal Void client formats from the reviewed current template."""
import argparse
import base64
import getpass
import hashlib
import json
import os
import time
import urllib.error
import urllib.request
import zlib
from pathlib import Path
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives.asymmetric.utils import decode_dss_signature
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

PUBLIC_KEY = 'MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEBvmVi6bDPa9eUOBNsYKr+IQ3JW3rQPQpeWxhi/fTTuLIn8jtG3vDb1G2y9286BKW1GKs2zksU9Grw6eFMHF7Aw=='
WORKER = 'https://dg.dynamongamer30.workers.dev'
# Filled with the COMPLETE current split template by the release packager.
TEMPLATE_B64 = ''

SUPPLIED_ENGINE_SHA256 = 'b6f5470f21360435bc98c868bad208d79ab03493d045598a8f3924b099f818eb'
SUPPLIED_ENGINE_EDITS_B64 = ''

def b64(value):
    return base64.b64encode(value).decode('ascii')

def prepare(original):
    template = json.loads(zlib.decompress(base64.b64decode(TEMPLATE_B64)))
    digest = hashlib.sha256(original).hexdigest()
    if digest == SUPPLIED_ENGINE_SHA256:
        template['original_sha256'] = digest
        template['edits'] = json.loads(zlib.decompress(base64.b64decode(SUPPLIED_ENGINE_EDITS_B64)))
    elif digest != template['original_sha256']:
        raise ValueError('Unsupported original game file. Found SHA-256: ' + digest + '. Supported SHA-256 values: ' + template['original_sha256'] + ' or ' + SUPPLIED_ENGINE_SHA256 + '. Use the unmodified local engine from the APK you will install. Nothing uploaded.')
    # Offsets in the JavaScript bundle are UTF-16 code units, not Python indices.
    source = original.decode('utf-8')
    units = source.encode('utf-16-le')
    previous = 0
    for edit in template['edits']:
        start, end = edit['start'], edit['end']
        if not isinstance(start, int) or not isinstance(end, int) or start < previous or end < start or end * 2 > len(units):
            raise ValueError('Invalid or overlapping patch offsets')
        previous = end
    for edit in reversed(template['edits']):
        units = units[:edit['start'] * 2] + edit['replacement'].encode('utf-16-le') + units[edit['end'] * 2:]
    game = units.decode('utf-16-le')
    globals_js = '\n;\n' + ''.join('window.' + key + '=' + json.dumps(template[field], ensure_ascii=True) + ';\n'
        for key, field in [('__DG_BRAND', 'brand'), ('__DG_MENU_CONFIG', 'menu'), ('__DG_CATALOG', 'catalog')])
    return (game + globals_js + template['runtime'] + '\n').encode('utf-8'), json.dumps(template, ensure_ascii=True, separators=(',', ':')).encode('utf-8')

def load_key(path):
    key = serialization.load_pem_private_key(path.read_bytes(), password=None)
    if not isinstance(key, ec.EllipticCurvePrivateKey) or not isinstance(key.curve, ec.SECP256R1):
        raise ValueError('Existing ECDSA P-256 signing key required')
    public = key.public_key().public_bytes(serialization.Encoding.DER, serialization.PublicFormat.SubjectPublicKeyInfo)
    if b64(public) != PUBLIC_KEY:
        raise ValueError('Signing key does not match the installed DEX. Nothing uploaded.')
    return key

def sign(key, value):
    r, s = decode_dss_signature(key.sign(value, ec.ECDSA(hashes.SHA256())))
    return b64(r.to_bytes(32, 'big') + s.to_bytes(32, 'big'))

def seal(payload, key, build, client, issued):
    aes, iv = os.urandom(32), os.urandom(12)
    ciphertext = AESGCM(aes).encrypt(iv, payload, None)
    digest = hashlib.sha256(ciphertext).hexdigest()
    message = ('DG-PAYLOAD-V2\n%s\n%s\n%s\n%s\n%s' % (build, digest, b64(iv), issued, client)).encode()
    return dict(build=build, protocol=2, min_client=client, issued=issued, ct_b64=b64(ciphertext),
                iv_b64=b64(iv), ct_sha=digest, sig_b64=sign(key, ciphertext), meta_sig_b64=sign(key, message), key_b64=b64(aes))

def make_bundle(original, key):
    legacy, split = prepare(original)
    issued = int(time.time())
    build = 'royalvoid-menu-fix-' + time.strftime('%Y%m%d-%H%M%S', time.gmtime()) + '-' + os.urandom(3).hex()
    bundle = dict(format='DG-ACTIVE-PAYLOAD-1', build=build,
        variants={'legacy': seal(legacy, key, build, 3, issued), 'split': seal(split, key, build, 4, issued)})
    if any(len(v['ct_b64']) > 10000000 for v in bundle['variants'].values()):
        raise ValueError('Worker payload size limit exceeded. Nothing uploaded.')
    return bundle

class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None

def upload(bundle, admin_key):
    request = urllib.request.Request(WORKER + '/admin/upload-payload', method='POST',
        data=json.dumps(bundle).encode(), headers={'Content-Type': 'application/json', 'X-Admin': admin_key,
            'Accept': 'application/json', 'User-Agent': 'Mozilla/5.0 RoyalVoidOwnerUpdater'})
    try:
        with urllib.request.build_opener(NoRedirect()).open(request, timeout=90) as response:
            result = json.loads(response.read(65536))
    except urllib.error.HTTPError as error:
        raise ValueError('Upload rejected: HTTP ' + str(error.code) + '. Check Worker/admin credentials.') from None
    except (urllib.error.URLError, TimeoutError):
        raise ValueError('Upload connection failed; check current_build before retrying.') from None
    if result.get('ok') is not True or result.get('build') != bundle['build']:
        raise ValueError('Worker did not confirm this build; check current_build before retrying.')

OWNER_ADMIN_KEY = ""  # Set only in your private phone copy; keep GitHub copy empty.

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--original', required=True, type=Path)
    parser.add_argument('--signing-key', required=True, type=Path)
    parser.add_argument('--bundle-out', type=Path, help='Private owner export; skips upload')
    parser.add_argument('--upload', action='store_true', help='Publish BOTH formats through the existing Worker admin route')
    args = parser.parse_args()
    if args.upload == bool(args.bundle_out):
        parser.error('Choose exactly one of --bundle-out or --upload')
    try:
        bundle = make_bundle(args.original.read_bytes(), load_key(args.signing_key))
        if args.bundle_out:
            with os.fdopen(os.open(args.bundle_out, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600), 'w') as stream:
                json.dump(bundle, stream)
            args.bundle_out.chmod(0o600)
            print('Private dual-client bundle exported. Contains AES keys: keep it off GitHub and out of the APK.')
        else:
            admin = os.environ.get('DG_ADMIN_KEY') or OWNER_ADMIN_KEY or getpass.getpass('Cloudflare ADMIN_KEY (hidden): ')
            if not admin:
                raise ValueError('Empty ADMIN_KEY; nothing uploaded')
            upload(bundle, admin)
            print('Published both client formats. Fully close/reopen the game and log in again.')
        print('Build: ' + bundle['build'])
    except (ValueError, OSError) as error:
        parser.exit(1, 'STOP: ' + str(error) + '\n')

if __name__ == '__main__':
    main()
